    'compliance.breadcrumb': { fr: 'Conformité', en: 'Compliance' },
    'compliance.eng.label': { fr: 'Notre Engagement', en: 'Our Commitment' },
    'compliance.eng.title': { fr: 'Une conformité sans compromis', en: 'Uncompromising Compliance' },
    'compliance.eng.lead': { fr: 'KGL Management attache une importance capitale à la conformité réglementaire, la gestion des risques et la transparence dans toutes ses interventions.', en: 'KGL Management attaches utmost importance to regulatory compliance, risk management and transparency in all its interventions.' },
    'compliance.eng.p1': { fr: 'Nous accompagnons les organisations dans la mise en place de systèmes de contrôle interne robustes, la cartographie des risques, la due diligence et la conformité aux normes nationales et internationales.', en: 'We support organizations in implementing robust internal control systems, risk mapping, due diligence and compliance with national and international standards.' },
    'compliance.eng.p2': { fr: 'Notre expertise en audit institutionnel, gestion des risques et conformité garantit que chaque projet respecte les meilleures pratiques et les exigences légales en vigueur.', en: 'Our expertise in institutional audit, risk management and compliance ensures that every project adheres to best practices and current legal requirements.' },
    'compliance.eng.f1': { fr: 'Conformité totale aux normes internationales', en: 'Full compliance with international standards' },
    'compliance.eng.f2': { fr: 'Transparence dans toutes nos interventions', en: 'Transparency in all our interventions' },
    'compliance.eng.f3': { fr: 'Protection contre la fraude et la corruption', en: 'Protection against fraud and corruption' },
