    'compliance.approach.label': { fr: 'Notre Approche', en: 'Our Approach' },
    'compliance.approach.title': { fr: 'Cadre de gestion des risques', en: 'Risk Management Framework' },
    'compliance.risk.r1.title': { fr: 'Cartographie des Risques', en: 'Risk Mapping' },
    'compliance.risk.r1.desc': { fr: 'Identification et évaluation systématique des risques opérationnels, financiers et stratégiques de votre organisation.', en: 'Systematic identification and evaluation of operational, financial and strategic risks of your organization.' },
    'compliance.risk.r2.title': { fr: 'Contrôle Interne', en: 'Internal Control' },
    'compliance.risk.r2.desc': { fr: 'Mise en place de procédures de contrôle interne efficaces pour sécuriser vos processus et prévenir les anomalies.', en: 'Implementation of effective internal control procedures to secure your processes and prevent anomalies.' },
    'compliance.risk.r3.title': { fr: 'Compliance', en: 'Compliance' },
    'compliance.risk.r3.desc': { fr: 'Assurance de la conformité aux réglementations locales et internationales applicables à votre secteur d\'activité.', en: 'Assurance of compliance with local and international regulations applicable to your business sector.' },
    'compliance.risk.r4.title': { fr: 'Anti-Fraude', en: 'Anti-Fraud' },
    'compliance.risk.r4.desc': { fr: 'Prévention, détection et investigation des fraudes pour protéger les actifs et la réputation de votre organisation.', en: 'Prevention, detection and investigation of fraud to protect the assets and reputation of your organization.' },
    'compliance.risk.r5.title': { fr: 'Due Diligence', en: 'Due Diligence' },
    'compliance.risk.r5.desc': { fr: 'Investigations approfondies pour évaluer les risques avant toute transaction ou partenariat stratégique.', en: 'Thorough investigations to assess risks before any strategic transaction or partnership.' },
    'compliance.risk.r6.title': { fr: 'Investigations', en: 'Investigations' },
