    'ceo.exp.e5': { fr: 'USAID, UE, FM, GAVI, BM, BAD', en: 'USAID, EU, GF, GAVI, WB, AfDB' },
    'ceo.bio.label': { fr: 'Biographie', en: 'Biography' },
    'ceo.bio.title': { fr: 'Parcours & Expertise', en: 'Career & Expertise' },
    'ceo.bio.lead': { fr: '<strong style="color: var(--primary-color)">Dr. John Kangolo Lunkamba</strong> est titulaire d\'un Doctorat en Administration des Affaires de Suisse, d\'un Master en Management International de l\'Université de Poitiers (France) et d\'une Licence en Finance et Comptabilité de la Haute École de Commerce de Kinshasa.', en: '<strong style="color: var(--primary-color)">Dr. John Kangolo Lunkamba</strong> holds a Doctorate in Business Administration from Switzerland, a Master in International Management from the University of Poitiers (France) and a Bachelor in Finance and Accounting from the Higher School of Commerce of Kinshasa.' },
    'ceo.bio.p1': { fr: 'Fort de plus de <strong style="color: var(--primary-color)">20 ans d\'expérience</strong>, il a occupé des postes de direction en finance, administration et gouvernance au sein d\'organisations internationales, d\'institutions publiques et d\'entreprises privées en RDC, en Ouganda et en République centrafricaine.', en: 'With over <strong style="color: var(--primary-color)">20 years of experience</strong>, he has held leadership positions in finance, administration and governance within international organizations, public institutions and private companies in the DRC, Uganda and the Central African Republic.' },
    'ceo.bio.p2': { fr: '<strong style="color: var(--primary-color)">Professeur Associé</strong> à la Haute École de Commerce de Kinshasa, auteur de plusieurs publications scientifiques et formateur en gestion financière, gouvernance et lutte contre la corruption, il est le fondateur et CEO de <strong style="color: var(--primary-color)">KGL Management, Business & Consulting</strong>, où il accompagne les organisations dans l\'amélioration de leur performance, de leur gouvernance et de leur développement durable.', en: '<strong style="color: var(--primary-color)">Associate Professor</strong> at the Higher School of Commerce of Kinshasa, author of several scientific publications and trainer in financial management, governance and fight against corruption, he is the founder and CEO of <strong style="color: var(--primary-color)">KGL Management, Business & Consulting</strong>, where he supports organizations in improving their performance, governance and sustainable development.' },
    'ceo.edu.label': { fr: 'Formation', en: 'Education' },
    'ceo.edu.title': { fr: 'Parcours Académique', en: 'Academic Background' },
    'ceo.edu.d1': { fr: 'Doctorat', en: 'Doctorate' },
    'ceo.edu.t1': { fr: 'Doctorat en Administration des Affaires', en: 'Doctorate in Business Administration' },
    'ceo.edu.p1': { fr: 'Suisse — Spécialisation en management stratégique et gouvernance d\'entreprise.', en: 'Switzerland — Specialization in strategic management and corporate governance.' },
    'ceo.edu.d2': { fr: 'Master', en: 'Master' },
    'ceo.edu.t2': { fr: 'Master en Management International', en: 'Master in International Management' },
    'ceo.edu.p2': { fr: 'Université de Poitiers, France — Management stratégique à l\'international.', en: 'University of Poitiers, France — Strategic management internationally.' },
    'ceo.edu.d3': { fr: 'Licence', en: 'Bachelor' },
    'ceo.edu.t3': { fr: 'Licence en Finance et Comptabilité', en: 'Bachelor in Finance and Accounting' },
    'ceo.edu.p3': { fr: 'Haute École de Commerce de Kinshasa (HEC-KIN) — Fondamentaux en finance et comptabilité.', en: 'Higher School of Commerce of Kinshasa (HEC-KIN) — Fundamentals in finance and accounting.' },
    'ceo.expC.label': { fr: 'Expérience', en: 'Experience' },
