    'ceo.expC.e1.title': { fr: 'Organisations Internationales', en: 'International Organizations' },
    'ceo.expC.e1.desc': { fr: 'Postes de direction en finance et administration au sein d\'organisations internationales majeures.', en: 'Leadership positions in finance and administration within major international organizations.' },
    'ceo.expC.e2.title': { fr: 'Institutions Publiques', en: 'Public Institutions' },
    'ceo.expC.e2.desc': { fr: 'Direction financière et gouvernance au sein d\'institutions publiques en RDC et en Afrique centrale.', en: 'Financial management and governance within public institutions in the DRC and Central Africa.' },
    'ceo.expC.e3.title': { fr: 'Entreprises Privées', en: 'Private Companies' },
    'ceo.expC.e3.desc': { fr: 'Conseil stratégique et management pour des entreprises privées en RDC, Ouganda et RCA.', en: 'Strategic advice and management for private companies in DRC, Uganda and CAR.' },
    'ceo.expC.e4.title': { fr: 'Enseignement & Recherche', en: 'Teaching & Research' },
    'ceo.expC.e4.desc': { fr: 'Professeur Associé à la HEC-Kinshasa, auteur de publications scientifiques et formateur expert.', en: 'Associate Professor at HEC-Kinshasa, author of scientific publications and expert trainer.' },
    'ceo.cta.title': { fr: 'Travaillons ensemble', en: 'Let\'s work together' },
    'ceo.cta.desc': { fr: 'Bénéficiez de l\'expertise du Dr. John Kangolo et de son équipe pour transformer votre organisation.', en: 'Benefit from the expertise of Dr. John Kangolo and his team to transform your organization.' },
